def pacificAtlantic(heights):
    if not heights or not heights[0]:
        return []
    m, n = len(heights), len(heights[0])

    def can_reach_pacific(r, c):
        visited = set()
        stack = [(r, c)]
        visited.add((r, c))
        while stack:
            curr_r, curr_c = stack.pop()
            if curr_r == 0 or curr_c == 0:
                return True
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                    if heights[nr][nc] <= heights[curr_r][curr_c]:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
        return False

    def can_reach_atlantic(r, c):
        visited = set()
        stack = [(r, c)]
        visited.add((r, c))
        while stack:
            curr_r, curr_c = stack.pop()
            if curr_r == m - 1 or curr_c == n - 1:
                return True
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                    if heights[nr][nc] <= heights[curr_r][curr_c]:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
        return False

    result = []
    for r in range(m):
        for c in range(n):
            if can_reach_pacific(r, c) and can_reach_atlantic(r, c):
                result.append([r, c])
    return result

